.bfc0ac24 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/CoefficientCollision.lean @@ -0,0 +1,109 @@ +import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Combining.Answers + +/-! +# Collision bounds for direct line coefficients + +This module bounds the probability that two distinct coefficient vectors give +the same value at a uniformly sampled affine parameter.  It uses the existing +coefficient-polynomial representation and Mathlib's univariate root count. + +## References + +- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:331-344` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1595-1603` +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT +open MIPStarRE.LDT.Preliminaries + +noncomputable section + +private theorem linePolynomialOfCoefficients_injective_at_degree +    {K : Type*} [Field K] (degree : ℕ) : +    Function.Injective +      (linePolynomialOfCoefficients (K := K) (c := degree)) := by +  classical +  intro a b hab +  funext i +  have hcoeff := congrArg (fun p : Polynomial K => p.coeff i.val) hab +  simp only [linePolynomialOfCoefficients, Polynomial.finsetSum_coeff, +    Polynomial.coeff_C_mul_X_pow] at hcoeff +  have ha : (∑ j, if i.val = j.val then a j else 0) = a i := by +    simpa only [Fin.ext_iff] using Fintype.sum_ite_eq i a +  have hb : (∑ j, if i.val = j.val then b j else 0) = b i := by +    simpa only [Fin.ext_iff] using Fintype.sum_ite_eq i b +  rw [ha, hb] at hcoeff +  exact hcoeff + +/-- Two distinct direct coefficient vectors of degree at most `degree` agree +at a uniformly sampled parameter with probability at most `degree / q`. + +This is a Lean-only auxiliary. The cited paper passages describe the coefficient +answer format and apply Schwartz-Zippel to a later multivariate collision term; +they do not state this exact univariate averaging bound. + +The estimate has no hypothesis `degree < q`; when the displayed bound exceeds +one it remains a valid, deliberately nontruncated root-count bound. -/ +theorem directCoefficientCollision_avg_le (D : DirectLdParams) (degree : ℕ) +    (a b : DirectDegPoly D degree) (hne : a ≠ b) : +    avgOver (uniformDistribution (DirectScalarQ D)) +        (fun t => if evalCoefficient a t = evalCoefficient b t then +          (1 : ℝ) else 0) ≤ +      (degree : ℝ) / (D.q : ℝ) := by +  classical +  let p := linePolynomialOfCoefficients a +  let p' := linePolynomialOfCoefficients b +  have hpoly_ne : p ≠ p' := by +    intro hpoly +    exact hne (linePolynomialOfCoefficients_injective_at_degree degree hpoly) +  let collisionSet : Finset (DirectScalarQ D) := +    Finset.univ.filter fun t => evalCoefficient a t = evalCoefficient b t +  have hcollision_card : collisionSet.card ≤ degree := by +    have hsub_ne : p - p' ≠ 0 := sub_ne_zero.mpr hpoly_ne +    have hsubset : collisionSet.val ⊆ (p - p').roots := by +      intro t ht +      have heval : p.eval t = p'.eval t := by +        simpa [collisionSet, p, p', linePolynomialOfCoefficients_eval] using ht +      apply (Polynomial.mem_roots hsub_ne).2 +      rw [Polynomial.IsRoot.def, Polynomial.eval_sub, sub_eq_zero] +      exact heval +    have hroot_card := Polynomial.card_le_degree_of_subset_roots +      (p := p - p') (Z := collisionSet) hsubset +    have hdegree : (p - p').natDegree ≤ max p.natDegree p'.natDegree := by +      simpa [sub_eq_add_neg, Polynomial.natDegree_neg] using +        (Polynomial.natDegree_add_le p (-p')) +    exact hroot_card.trans <| hdegree.trans <| max_le +      (linePolynomialOfCoefficients_natDegree_le a) +      (linePolynomialOfCoefficients_natDegree_le b) +  calc +    avgOver (uniformDistribution (DirectScalarQ D)) +        (fun t => if evalCoefficient a t = evalCoefficient b t then +          (1 : ℝ) else 0) = +        (collisionSet.card : ℝ) / +          Fintype.card (DirectScalarQ D) := by +      calc +        avgOver (uniformDistribution (DirectScalarQ D)) +            (fun t => if evalCoefficient a t = evalCoefficient b t then +              (1 : ℝ) else 0) = +            ∑ t : DirectScalarQ D, +              if evalCoefficient a t = evalCoefficient b t then +                (1 / Fintype.card (DirectScalarQ D) : ℝ) else 0 := by +          simp [avgOver, uniformDistribution] +        _ = ∑ _t ∈ collisionSet, +              (1 / Fintype.card (DirectScalarQ D) : ℝ) := by +          rw [← Finset.sum_filter] +        _ = (collisionSet.card : ℝ) / +              Fintype.card (DirectScalarQ D) := by +          simp [div_eq_mul_inv] +    _ ≤ (degree : ℝ) / Fintype.card (DirectScalarQ D) := by +      exact div_le_div_of_nonneg_right (by exact_mod_cast hcollision_card) (by positivity) +    _ = (degree : ℝ) / (D.q : ℝ) := by +      rw [card_directScalarQ] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/CoefficientConsistency.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/CoefficientConsistency.lean new file mode 100644 index 00000000..751ed919 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/CoefficientConsistency.lean @@ -0,0 +1,64 @@ +import MIPStarRE.QPBT.Combining.DirectLowDegree.CoefficientCollision +import MIPStarRE.QPBT.Games.Sandwich.Support + +/-! +# Consistency of direct coefficient measurements + +This module lifts consistency of uniformly evaluated coefficient-vector POVMs +to consistency of their full coefficient outcomes.  The loss is the direct +univariate collision bound `degree / q`. + +## References + +- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:331-344` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1595-1603` +- Blueprint `lem:sandwich-codeword-defect` +-/ + +open scoped BigOperators MatrixOrder Matrix ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +/-- The consistency defect of two coefficient-vector POVM families is at most +their consistency defect after evaluation at an independent uniform parameter, +plus `degree / q`. + +This is a formalization-only specialization of +`SandwichProduct.consistencyDefect_codewords_le_evaluated_add`.  It applies to +arbitrary POVMs and retains all degrees, including `degree ≥ q`. -/ +theorem consistencyDefect_directCoefficients_le_evaluated_add +    {X ιA ιB : Type*} +    [Fintype X] [DecidableEq X] +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) (μ : Distribution X) +    (A : X → Measurement (DirectDegPoly D degree) ιA) +    (B : X → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) +    (hμ : μ.IsProbability) (hψ : ‖ψ‖ = 1) : +    consistencyDefect μ +        (fun x coefficients => heteroKron ((A x).effect coefficients) 1) +        (fun x coefficients => heteroKron 1 ((B x).effect coefficients)) ψ ≤ +      consistencyDefect +        (Distribution.prod μ (uniformDistribution (DirectScalarQ D))) +        (fun xt value => heteroKron +          (((A xt.1).postprocess +            (fun coefficients => evalCoefficient coefficients xt.2)).effect value) 1) +        (fun xt value => heteroKron 1 +          (((B xt.1).postprocess +            (fun coefficients => evalCoefficient coefficients xt.2)).effect value)) ψ + +        (degree : ℝ) / (D.q : ℝ) := by +  apply SandwichProduct.consistencyDefect_codewords_le_evaluated_add +      μ A B ψ (fun coefficients t => evalCoefficient coefficients t) +      ((degree : ℝ) / (D.q : ℝ)) hμ hψ +  · positivity +  · intro a b hne +    exact directCoefficientCollision_avg_le D degree a b hne + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean new file mode 100644 index 00000000..0b9480f3 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean @@ -0,0 +1,45 @@ +import MIPStarRE.QPBT.Combining.DirectLowDegree.ResampledCoefficientConsistency + +/-! +# Extended direct coefficient-collision loss + +This module compares the sum of the axis and diagonal coefficient-collision +losses at the extended directly indexed parameters with the original `m*d/q` +ratio. + +## References + +- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:331-344` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1595-1603` +-/ + +namespace MIPStarRE.QPBT + +/-- The axis loss `d/q` plus the diagonal loss `(2m+2)d/q` at the extended +direct parameters is at most five times the original loss `md/q`. + +This is a Lean-only scalar auxiliary for combining the two coefficient-POVM +consistency estimates. It uses only admissibility of the original parameters. -/ +theorem extendedDirectLd_coefficientCollisionLoss_le_five_mul +    (P : AdmissibleParams) : +    ((P.extendedDirectLd.d : ℝ) + +        (P.extendedDirectLd.m * P.extendedDirectLd.d : ℝ)) / +        (P.extendedDirectLd.q : ℝ) ≤ +      5 * ((P.m * P.d : ℝ) / (P.q : ℝ)) := by +  have hm : (1 : ℝ) ≤ (P.m : ℝ) := by +    exact_mod_cast P.one_le_m +  have hqNat : 0 < P.q := by +    rcases P.hq with ⟨k, _, hk⟩ +    rw [hk] +    exact Nat.pow_pos (by decide) +  have hq : (0 : ℝ) < (P.q : ℝ) := by +    exact_mod_cast hqNat +  change ((P.d : ℝ) + ((2 * P.m + 2 : ℕ) : ℝ) * (P.d : ℝ)) / +      (P.q : ℝ) ≤ 5 * ((P.m : ℝ) * (P.d : ℝ) / (P.q : ℝ)) +  push_cast +  rw [show 5 * ((P.m : ℝ) * (P.d : ℝ) / (P.q : ℝ)) = +    (5 * ((P.m : ℝ) * (P.d : ℝ))) / (P.q : ℝ) by ring] +  apply (div_le_div_iff_of_pos_right hq).2 +  nlinarith [show (0 : ℝ) ≤ (P.d : ℝ) by positivity] + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean index ba01f6cc..7a80d507 100644 --- a/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean @@ -88,7 +88,7 @@ instance (D : DirectLdParams) : Nonempty (DirectLdSpace D) :=    /-- Decompose a direct sample into its point and the remaining independent  coordinates. -/ -private def directLdSpacePointEquiv (D : DirectLdParams) : +def directLdSpacePointEquiv (D : DirectLdParams) :      DirectLdSpace D ≃        (Fin D.m → DirectScalarQ D) ×          (Fin D.m × (Fin D.m → DirectScalarQ D)) where @@ -142,6 +142,45 @@ inductive DirectLineDesc (D : DirectLdParams) where        (prefixZero : ∀ j : Fin D.m, j.val < index.val → direction j = 0)    deriving DecidableEq   +/-! ## Finite direct-line carrier -/ + +/-- A finite code for directly indexed lines, omitting only proof fields. -/ +private abbrev DirectLineDescCode (D : DirectLdParams) := +  ((Fin D.m → DirectScalarQ D) × Fin D.m) ⊕ +    ((Fin D.m → DirectScalarQ D) × Fin D.m × +      (Fin D.m → DirectScalarQ D)) + +/-- Encode a directly indexed line by its tag and mathematical data. -/ +private def directLineDescCode (D : DirectLdParams) : +    DirectLineDesc D → DirectLineDescCode D +  | .axis base index _ => .inl (base, index) +  | .diagonal base index direction _ _ => .inr (base, index, direction) + +/-- The direct-line code is injective by proof irrelevance. -/ +private theorem directLineDescCode_injective (D : DirectLdParams) : +    Function.Injective (directLineDescCode D) := by +  intro line line' h +  cases line with +  | axis base index baseFixed => +      cases line' with +      | axis base' index' baseFixed' => +          simp only [directLineDescCode, Sum.inl.injEq, Prod.mk.injEq] at h +          rcases h with ⟨rfl, rfl⟩ +          rfl +      | diagonal => simp [directLineDescCode] at h +  | diagonal base index direction baseFixed prefixZero => +      cases line' with +      | axis => simp [directLineDescCode] at h +      | diagonal base' index' direction' baseFixed' prefixZero' => +          simp only [directLineDescCode, Sum.inr.injEq, Prod.mk.injEq] at h +          rcases h with ⟨rfl, rfl, rfl⟩ +          rfl + +/-- Directly indexed line descriptions form a finite type. -/ +noncomputable instance directLineDescFintype (D : DirectLdParams) : +    Fintype (DirectLineDesc D) := +  Fintype.ofInjective (directLineDescCode D) (directLineDescCode_injective D) +  /-- The kind of a directly indexed line. -/  def DirectLineDesc.kind {D : DirectLdParams} : DirectLineDesc D → LineKind    | .axis _ _ _ => .axis diff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean new file mode 100644 index 00000000..63ca6b54 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean @@ -0,0 +1,45 @@ +import MIPStarRE.QPBT.Combining.DirectLowDegree.GameValue + +/-! # Probability bounds for the directly indexed low-degree game + +This module records two elementary probability bounds needed when a caller caps an +assembled direct-game rejection estimate by one. The results are formalization-only +support: they do not bound any individual game branch or prove a passing-value theorem. + +## References + +- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:178-186` +- Parent issue #119 and arithmetic issue #333 +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT + +namespace Strategy + +/-- Every tensor-product strategy has nonnegative value. -/ +theorem value_nonneg {G : Game} (S : Strategy G) : 0 ≤ S.value := by +  unfold value +  apply avgOver_nonneg +  intro questions +  apply Finset.sum_nonneg +  intro answerA _ +  apply Finset.sum_nonneg +  intro answerB _ +  split +  · exact outcomeWeight_nonneg S questions.1 questions.2 answerA answerB +  · exact le_rfl + +end Strategy + +/-- The total rejection probability of a directly indexed low-degree strategy is at +most one. This is the probability cap used by scalar error envelopes; it gives no +quantitative branch estimate. -/ +theorem directLdRejectionProbability_le_one +    (D : DirectLdParams) (S : Strategy (directLdGame D)) : +    directLdRejectionProbability D S ≤ 1 := by +  rw [directLdRejectionProbability_eq_one_sub_value] +  linarith [S.value_nonneg] + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean new file mode 100644 index 00000000..67dadf75 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean @@ -0,0 +1,237 @@ +import MIPStarRE.QPBT.Combining.DirectLowDegree.CoefficientConsistency +import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.LineResampling + +/-! +# Resampled consistency of direct coefficient measurements + +This module reexpresses the consistency defect of uniformly evaluated direct +coefficient measurements over the original joint line-point distributions. +For a zero direction, the sampled point does not determine the affine +parameter, so the joint integrand retains the full uniform parameter average. + +## References + +- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:243-344` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1116` +-/ + +open scoped BigOperators MatrixOrder Matrix ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum +open DistanceCalculus + +noncomputable section + +/-- The pointwise consistency defect of two direct coefficient measurements +after evaluating both coefficient vectors at the parameter `t`. -/ +noncomputable def directCoefficientEvaluationDefect +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) +    (line : DirectLineDesc D) (t : DirectScalarQ D) : Error := +  ∑ a : DirectScalarQ D, ∑ b : DirectScalarQ D, if a = b then 0 else +    stateQForm ψ +      (heteroKron +        (((A line).postprocess +          (fun coefficients => evalCoefficient coefficients t)).effect a) +        (((B line).postprocess +          (fun coefficients => evalCoefficient coefficients t)).effect b)) + +/-- The evaluated coefficient defect as a function of a joint direct +line-point sample. For a zero direction the point is independent of the +uniform affine parameter, so this definition retains that entire average +rather than selecting a distinguished parameter. -/ +noncomputable def directJointCoefficientEvaluationDefect +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) +    (sample : DirectLineDesc D × (Fin D.m → DirectScalarQ D)) : Error := +  if sample.1.direction = 0 then +    avgOver (uniformDistribution (DirectScalarQ D)) +      (fun t => directCoefficientEvaluationDefect D degree A B ψ sample.1 t) +  else +    directCoefficientEvaluationDefect D degree A B ψ sample.1 +      (directLineRepParameter sample.1.direction sample.2) + +private theorem directLineRepParameter_base_add_smul +    (D : DirectLdParams) (line : DirectLineDesc D) +    (hdir : line.direction ≠ 0) (t : DirectScalarQ D) : +    directLineRepParameter line.direction +        (line.base + t • line.direction) = t := by +  apply directLineRepParameter_eq_of_nonzero hdir +  rw [lineRepMap_add_smul, line.base_fixed] + +private theorem avgOver_directJointCoefficientEvaluationDefect_affine +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) (line : DirectLineDesc D) : +    avgOver (uniformDistribution (DirectScalarQ D)) +        (fun t => directCoefficientEvaluationDefect D degree A B ψ line t) = +      avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +        directJointCoefficientEvaluationDefect D degree A B ψ +          (line, line.base + t • line.direction)) := by +  by_cases hdir : line.direction = 0 +  · simp [directJointCoefficientEvaluationDefect, hdir, avgOver_uniform_const] +  · apply avgOver_congr +    intro t +    simp [directJointCoefficientEvaluationDefect, hdir, +      directLineRepParameter_base_add_smul D line hdir t] + +/-- Uniform parameter evaluation over the axis-line marginal is exactly the +joint axis-line/point expectation of the corresponding coefficient defect. -/ +theorem avgOver_directALinePointDist_coefficientEvaluation +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    avgOver ((directALinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) +          (fun t => directCoefficientEvaluationDefect D degree A B ψ line t)) = +      avgOver (directALinePointDist D) +        (directJointCoefficientEvaluationDefect D degree A B ψ) := by +  calc +    _ = avgOver ((directALinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          directJointCoefficientEvaluationDefect D degree A B ψ +            (line, line.base + t • line.direction))) := by +      apply avgOver_congr +      exact avgOver_directJointCoefficientEvaluationDefect_affine D degree A B ψ +    _ = _ := avgOver_directALinePointDist_resample D +      (directJointCoefficientEvaluationDefect D degree A B ψ) + +/-- Uniform parameter evaluation over the diagonal-line marginal is exactly +the joint diagonal-line/point expectation of the corresponding coefficient +defect, including zero-direction samples. -/ +theorem avgOver_directDLinePointDist_coefficientEvaluation +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    avgOver ((directDLinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) +          (fun t => directCoefficientEvaluationDefect D degree A B ψ line t)) = +      avgOver (directDLinePointDist D) +        (directJointCoefficientEvaluationDefect D degree A B ψ) := by +  calc +    _ = avgOver ((directDLinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          directJointCoefficientEvaluationDefect D degree A B ψ +            (line, line.base + t • line.direction))) := by +      apply avgOver_congr +      exact avgOver_directJointCoefficientEvaluationDefect_affine D degree A B ψ +    _ = _ := avgOver_directDLinePointDist_resample D +      (directJointCoefficientEvaluationDefect D degree A B ψ) + +/-- The product-law consistency defect of evaluated direct coefficient POVMs +over axis lines is the corresponding original joint line-point expectation. -/ +theorem consistencyDefect_directALine_coefficients_evaluated_eq_joint +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    consistencyDefect +        (Distribution.prod ((directALinePointDist D).map Prod.fst) +          (uniformDistribution (DirectScalarQ D))) +        (fun lt value => heteroKron +          (((A lt.1).postprocess +            (fun coefficients => evalCoefficient coefficients lt.2)).effect value) 1) +        (fun lt value => heteroKron 1 +          (((B lt.1).postprocess +            (fun coefficients => evalCoefficient coefficients lt.2)).effect value)) ψ = +      avgOver (directALinePointDist D) +        (directJointCoefficientEvaluationDefect D degree A B ψ) := by +  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point, +    SandwichProduct.avgOver_distribution_prod] +  exact avgOver_directALinePointDist_coefficientEvaluation D degree A B ψ + +/-- The product-law consistency defect of evaluated direct coefficient POVMs +over diagonal lines is the corresponding original joint line-point +expectation, including zero-direction samples. -/ +theorem consistencyDefect_directDLine_coefficients_evaluated_eq_joint +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) : +    consistencyDefect +        (Distribution.prod ((directDLinePointDist D).map Prod.fst) +          (uniformDistribution (DirectScalarQ D))) +        (fun lt value => heteroKron +          (((A lt.1).postprocess +            (fun coefficients => evalCoefficient coefficients lt.2)).effect value) 1) +        (fun lt value => heteroKron 1 +          (((B lt.1).postprocess +            (fun coefficients => evalCoefficient coefficients lt.2)).effect value)) ψ = +      avgOver (directDLinePointDist D) +        (directJointCoefficientEvaluationDefect D degree A B ψ) := by +  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point, +    SandwichProduct.avgOver_distribution_prod] +  exact avgOver_directDLinePointDist_coefficientEvaluation D degree A B ψ + +/-- Coefficient consistency over the axis-line marginal is bounded by its +original joint line-point evaluation defect plus `degree / q`. -/ +theorem consistencyDefect_directALine_coefficients_le_joint_add +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) (hψ : ‖ψ‖ = 1) : +    consistencyDefect ((directALinePointDist D).map Prod.fst) +        (fun line coefficients => heteroKron ((A line).effect coefficients) 1) +        (fun line coefficients => heteroKron 1 ((B line).effect coefficients)) ψ ≤ +      avgOver (directALinePointDist D) +          (directJointCoefficientEvaluationDefect D degree A B ψ) + +        (degree : ℝ) / (D.q : ℝ) := by +  have h := consistencyDefect_directCoefficients_le_evaluated_add +    D degree ((directALinePointDist D).map Prod.fst) A B ψ +    ((directALinePointDist_isProbability D).map Prod.fst) hψ +  rw [consistencyDefect_directALine_coefficients_evaluated_eq_joint +    D degree A B ψ] at h +  exact h + +/-- Coefficient consistency over the diagonal-line marginal is bounded by its +original joint line-point evaluation defect plus `degree / q`, with no +nonzero-direction restriction. -/ +theorem consistencyDefect_directDLine_coefficients_le_joint_add +    {ιA ιB : Type*} +    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB] +    (D : DirectLdParams) (degree : ℕ) +    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA) +    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB) +    (ψ : EuclideanSpace ℂ (ιA × ιB)) (hψ : ‖ψ‖ = 1) : +    consistencyDefect ((directDLinePointDist D).map Prod.fst) +        (fun line coefficients => heteroKron ((A line).effect coefficients) 1) +        (fun line coefficients => heteroKron 1 ((B line).effect coefficients)) ψ ≤ +      avgOver (directDLinePointDist D) +          (directJointCoefficientEvaluationDefect D degree A B ψ) + +  