.index, sample.direction⟩ +  left_inv sample := by +    cases sample with +    | mk point index direction => +        simp [add_assoc] +  right_inv sample := by +    cases sample with +    | mk point index direction => +        simp [add_assoc] + +@[simp] private theorem directLdSpacePointTranslateEquiv_apply +    (D : DirectLdParams) +    (directionOf : Fin D.m → (Fin D.m → DirectScalarQ D) → +      (Fin D.m → DirectScalarQ D)) +    (t : DirectScalarQ D) (sample : DirectLdSpace D) : +    directLdSpacePointTranslateEquiv D directionOf t sample = +      ⟨sample.point + t • directionOf sample.index sample.direction, +        sample.index, sample.direction⟩ := rfl + +@[simp] private theorem directLdSpacePointTranslateEquiv_symm_apply +    (D : DirectLdParams) +    (directionOf : Fin D.m → (Fin D.m → DirectScalarQ D) → +      (Fin D.m → DirectScalarQ D)) +    (t : DirectScalarQ D) (sample : DirectLdSpace D) : +    (directLdSpacePointTranslateEquiv D directionOf t).symm sample = +      ⟨sample.point + (-t) • directionOf sample.index sample.direction, +        sample.index, sample.direction⟩ := rfl + +/-- Uniformly resampling a canonical affine line by a scalar parameter +recovers its original joint line-point sample. -/ +private theorem avgOver_directLinePoint_resample +    (D : DirectLdParams) +    (directionOf : Fin D.m → (Fin D.m → DirectScalarQ D) → +      (Fin D.m → DirectScalarQ D)) +    (lineOf : DirectLdSpace D → DirectLineDesc D) +    (hbase : ∀ sample, +      (lineOf sample).base = +        lineRepMap (directionOf sample.index sample.direction) sample.point) +    (hdirection : ∀ sample, +      (lineOf sample).direction = directionOf sample.index sample.direction) +    (hline : ∀ sample t, +      lineOf (directLdSpacePointTranslateEquiv D directionOf t sample) = +        lineOf sample) +    (F : (DirectLineDesc D × (Fin D.m → DirectScalarQ D)) → Error) : +    avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            (lineOf sample).base + t • (lineOf sample).direction))) = +      avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +        F (lineOf sample, sample.point)) := by +  have hparameter : ∀ sample, +      avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            (lineOf sample).base + t • (lineOf sample).direction)) = +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) := by +    intro sample +    let direction := directionOf sample.index sample.direction +    let r := directLineRepParameter direction sample.point +    calc +      avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            (lineOf sample).base + t • (lineOf sample).direction)) = +          avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +            F (lineOf sample, +              (lineOf sample).base + +                ((Equiv.addRight (-r)).symm t) • +                  (lineOf sample).direction)) := +        avgOver_uniform_equiv (Equiv.addRight (-r)) _ +      _ = avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) := by +        apply avgOver_congr +        intro t +        congr 2 +        rw [hdirection, hbase] +        have hadd : (Equiv.addRight (-r)).symm t = t + r := by +          simp +        rw [hadd] +        change lineRepMap direction sample.point + (t + r) • direction = +          sample.point + t • direction +        rw [add_comm t r, add_smul, ← add_assoc, +          ← directLineRepParameter_spec direction sample.point] +  have hsample : ∀ t : DirectScalarQ D, +      avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) = +        avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, sample.point)) := by +    intro t +    calc +      avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction)) = +          avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +            F (lineOf ((directLdSpacePointTranslateEquiv D directionOf t).symm sample), +              ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).point + +                t • directionOf +                  ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).index +                  ((directLdSpacePointTranslateEquiv D directionOf t).symm sample).direction)) := +        avgOver_uniform_equiv (directLdSpacePointTranslateEquiv D directionOf t) _ +      _ = avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, sample.point)) := by +        apply avgOver_congr +        intro sample +        congr 2 +        · change lineOf (directLdSpacePointTranslateEquiv D directionOf (-t) sample) = +            lineOf sample +          exact hline sample (-t) +        · rw [directLdSpacePointTranslateEquiv_symm_apply] +          simp [add_assoc] +  calc +    avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (lineOf sample, +            (lineOf sample).base + t • (lineOf sample).direction))) = +        avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +            F (lineOf sample, +              sample.point + +                t • directionOf sample.index sample.direction))) := by +      apply avgOver_congr +      exact hparameter +    _ = avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +        avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, +            sample.point + +              t • directionOf sample.index sample.direction))) := +      avgOver_uniform_comm _ +    _ = avgOver (uniformDistribution (DirectScalarQ D)) (fun _ => +        avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +          F (lineOf sample, sample.point))) := by +      apply avgOver_congr +      exact hsample +    _ = avgOver (uniformDistribution (DirectLdSpace D)) (fun sample => +        F (lineOf sample, sample.point)) := avgOver_uniform_const _ + +/-- Sampling an axis line with its marginal and then a uniform affine +parameter reproduces the original joint axis-line/point distribution. -/ +theorem avgOver_directALinePointDist_resample +    (D : DirectLdParams) +    (F : (DirectLineDesc D × (Fin D.m → DirectScalarQ D)) → Error) : +    avgOver ((directALinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (line, line.base + t • line.direction))) = +      avgOver (directALinePointDist D) F := by +  simp only [directALinePointDist, Distribution.avgOver_map] +  apply avgOver_directLinePoint_resample D +      (fun (index : Fin D.m) (_ : Fin D.m → DirectScalarQ D) => +        coordinateDirection index) +      (directALineDescOf D) +  · intro sample +    rfl +  · intro sample +    rfl +  · intro sample t +    rw [directLdSpacePointTranslateEquiv_apply] +    simp only [directALineDescOf] +    simp [lineRepMap_add_smul] + +/-- Sampling a prefix-diagonal line with its marginal and then a uniform +affine parameter reproduces the original joint diagonal-line/point +distribution, including samples with zero direction. -/ +theorem avgOver_directDLinePointDist_resample +    (D : DirectLdParams) +    (F : (DirectLineDesc D × (Fin D.m → DirectScalarQ D)) → Error) : +    avgOver ((directDLinePointDist D).map Prod.fst) (fun line => +        avgOver (uniformDistribution (DirectScalarQ D)) (fun t => +          F (line, line.base + t • line.direction))) = +      avgOver (directDLinePointDist D) F := by +  simp only [directDLinePointDist, Distribution.avgOver_map] +  apply avgOver_directLinePoint_resample D +      (fun (index : Fin D.m) (direction : Fin D.m → DirectScalarQ D) => +        directPrefixProjection index direction) +      (directDLineDescOf D) +  · intro sample +    rfl +  · intro sample +    rfl +  · intro sample t +    rw [directLdSpacePointTranslateEquiv_apply] +    simp only [directDLineDescOf] +    simp [lineRepMap_add_smul] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean b/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean new file mode 100644 index 00000000..4211a24f --- /dev/null +++ b/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean @@ -0,0 +1,154 @@ +import MIPStarRE.QPBT.Combining.ExtendedLineGame.ParameterEvaluatedLineBound +import MIPStarRE.QPBT.Combining.ExtendedLineGame.SameLineCoefficientBound + +/-! +# Transport of the axis parameter-evaluation defect + +The coefficient-evaluation defect for the same-axis branch equals the +parameter-evaluation defect of the supplied direct-game strategy. Both sample +the actual axis-line marginal and an independent uniform affine parameter. +Composing the strategy's answer map with coefficient extraction gives +`axisRead`. The degree-support field of the supplied line measurements also +identifies this truncated evaluation with the original coefficient evaluation. + +These are formalization-only identities for the construction in the proof of +`lem:qld-4-7`; they neither construct the supplied witness nor prove the source +theorem. + +## References + +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1034` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288` +- Blueprint `lem:qld-4-7`. +- Issue #351. +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +namespace ExtendedLineGame + +variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real} +variable {setting : ProjectiveSetting P epsilon} +variable {points : CombinedPointsWitness setting deltaQ} + +/-- A pair of axis outcomes has zero Born mass if either coefficient vector +exceeds degree `d`. This is the degree-support conclusion of `lem:qld-4-13` +applied before any truncation or evaluation of the outcomes. -/ +theorem axis_coefficient_born_mass_eq_zero_of_unsupported +    (lines : ExtendedLinesWitness setting points deltaL) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (coefficientsA coefficientsB : DirectDegPoly P.extendedDirectLd (P.m * P.d + 1)) +    (hunsupported : (¬ ∀ index, P.d < index.val → coefficientsA index = 0) ∨ +      (¬ ∀ index, P.d < index.val → coefficientsB index = 0)) : +    DistanceCalculus.stateQForm (pairState setting) +      (heteroKron ((lines.Qline .alice line).effect coefficientsA) +        ((lines.Qline .bob line).effect coefficientsB)) = 0 := by +  rcases hunsupported with hA | hB +  · rw [lines.axis_degree .alice line coefficientsA hline hA] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] +  · rw [lines.axis_degree .bob line coefficientsB hline hB] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] + +/-- Truncating an axis coefficient answer and evaluating it has exactly the +same measurement effects as evaluating the original answer. The discarded +coefficients vanish on every nonzero effect by the final assertion of +`lem:qld-4-13`, encoded in `ExtendedLinesWitness.axis_degree`. -/ +theorem axis_parameter_evaluation_effect_eq +    (lines : ExtendedLinesWitness setting points deltaL) (side : PlayerSide) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (parameter value : DirectScalarQ P.extendedDirectLd) : +    ((((lines.Qline side line).postprocess (axisRead P)).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) = +      (((lines.Qline side line).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) := by +  classical +  rw [MIPStarRE.Quantum.Measurement.postprocess_comp] +  simp only [MIPStarRE.Quantum.Measurement.postprocess_effect, Finset.sum_filter] +  apply Finset.sum_congr rfl +  intro coefficients _ +  by_cases heffect : (lines.Qline side line).effect coefficients = 0 +  · simp [heffect] +  · rw [axisRead_eval_of_effect_ne_zero lines side line hline coefficients heffect] + +/-- The axis coefficient-evaluation defect is exactly the parameter-evaluation +defect of the supplied strategy. The identity uses finite postprocessing and +the unchanged product of the axis-line marginal with a uniform parameter; +it introduces no degree, projectivity, or passing-value hypothesis. -/ +theorem axis_parameter_evaluated_coefficient_defect_eq +    (lines : ExtendedLinesWitness setting points deltaL) : +    axisParameterEvaluatedCoefficientDefect lines = +      axisParameterEvaluationDefect lines := by +  classical +  let readAxis : DirectLdAnswer P.extendedDirectLd → +      DirectDegPoly P.extendedDirectLd P.d := fun answer => +    match answer with +    | .alinePolys coefficients => coefficients ⟨0, by change 0 < 1; decide⟩ +    | _ => 0 +  let law := Distribution.prod (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (uniformDistribution (DirectScalarQ P.extendedDirectLd)) +  have heffect (side : PlayerSide) (sample : DirectLdSpace P.extendedDirectLd) +      (parameter value : DirectScalarQ P.extendedDirectLd) : +      ((((lines.Qline side (directALineDescOf P.extendedDirectLd sample)).postprocess +          (axisRead P)).postprocess +            (fun coefficients => evalCoefficient 