ssue #351. +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +namespace ExtendedLineGame + +variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real} +variable {setting : ProjectiveSetting P epsilon} +variable {points : CombinedPointsWitness setting deltaQ} + +/-- A pair of axis outcomes has zero Born mass if either coefficient vector +exceeds degree `d`. This is the degree-support conclusion of `lem:qld-4-13` +applied before any truncation or evaluation of the outcomes. -/ +theorem axis_coefficient_born_mass_eq_zero_of_unsupported +    (lines : ExtendedLinesWitness setting points deltaL) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (coefficientsA coefficientsB : DirectDegPoly P.extendedDirectLd (P.m * P.d + 1)) +    (hunsupported : (¬ ∀ index, P.d < index.val → coefficientsA index = 0) ∨ +      (¬ ∀ index, P.d < index.val → coefficientsB index = 0)) : +    DistanceCalculus.stateQForm (pairState setting) +      (heteroKron ((lines.Qline .alice line).effect coefficientsA) +        ((lines.Qline .bob line).effect coefficientsB)) = 0 := by +  rcases hunsupported with hA | hB +  · rw [lines.axis_degree .alice line coefficientsA hline hA] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] +  · rw [lines.axis_degree .bob line coefficientsB hline hB] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] + +/-- Truncating an axis coefficient answer and evaluating it has exactly the +same measurement effects as evaluating the original answer. The discarded +coefficients vanish on every nonzero effect by the final assertion of +`lem:qld-4-13`, encoded in `ExtendedLinesWitness.axis_degree`. -/ +theorem axis_parameter_evaluation_effect_eq +    (lines : ExtendedLinesWitness setting points deltaL) (side : PlayerSide) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (parameter value : DirectScalarQ P.extendedDirectLd) : +    ((((lines.Qline side line).postprocess (axisRead P)).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) = +      (((lines.Qline side line).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) := by +  classical +  rw [MIPStarRE.Quantum.Measurement.postprocess_comp] +  simp only [MIPStarRE.Quantum.Measurement.postprocess_effect, Finset.sum_filter] +  apply Finset.sum_congr rfl +  intro coefficients _ +  by_cases heffect : (lines.Qline side line).effect coefficients = 0 +  · simp [heffect] +  · rw [axisRead_eval_of_effect_ne_zero lines side line hline coefficients heffect] + +/-- The axis coefficient-evaluation defect is exactly the parameter-evaluation +defect of the supplied strategy. The identity uses finite postprocessing and +the unchanged product of the axis-line marginal with a uniform parameter; +it introduces no degree, projectivity, or passing-value hypothesis. -/ +theorem axis_parameter_evaluated_coefficient_defect_eq +    (lines : ExtendedLinesWitness setting points deltaL) : +    axisParameterEvaluatedCoefficientDefect lines = +      axisParameterEvaluationDefect lines := by +  classical +  let readAxis : DirectLdAnswer P.extendedDirectLd → +      DirectDegPoly P.extendedDirectLd P.d := fun answer => +    match answer with +    | .alinePolys coefficients => coefficients ⟨0, by change 0 < 1; decide⟩ +    | _ => 0 +  let law := Distribution.prod (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (uniformDistribution (DirectScalarQ P.extendedDirectLd)) +  have heffect (side : PlayerSide) (sample : DirectLdSpace P.extendedDirectLd) +      (parameter value : DirectScalarQ P.extendedDirectLd) : +      ((((lines.Qline side (directALineDescOf P.extendedDirectLd sample)).postprocess +          (axisRead P)).postprocess +            (fun coefficients => evalCoefficient coefficients parameter)).effect value)