 F (line, line.base + t • line.direction))) = +      avgOver (directDLinePointDist D) F := by +  simp only [directDLinePointDist, Distribution.avgOver_map] +  apply avgOver_directLinePoint_resample D +      (fun (index : Fin D.m) (direction : Fin D.m → DirectScalarQ D) => +        directPrefixProjection index direction) +      (directDLineDescOf D) +  · intro sample +    rfl +  · intro sample +    rfl +  · intro sample t +    rw [directLdSpacePointTranslateEquiv_apply] +    simp only [directDLineDescOf] +    simp [lineRepMap_add_smul] + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean b/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean new file mode 100644 index 00000000..4211a24f --- /dev/null +++ b/MIPStarRE/QPBT/Combining/ExtendedLineGame/AxisParameterDefectTransport.lean @@ -0,0 +1,154 @@ +import MIPStarRE.QPBT.Combining.ExtendedLineGame.ParameterEvaluatedLineBound +import MIPStarRE.QPBT.Combining.ExtendedLineGame.SameLineCoefficientBound + +/-! +# Transport of the axis parameter-evaluation defect + +The coefficient-evaluation defect for the same-axis branch equals the +parameter-evaluation defect of the supplied direct-game strategy. Both sample +the actual axis-line marginal and an independent uniform affine parameter. +Composing the strategy's answer map with coefficient extraction gives +`axisRead`. The degree-support field of the supplied line measurements also +identifies this truncated evaluation with the original coefficient evaluation. + +These are formalization-only identities for the construction in the proof of +`lem:qld-4-7`; they neither construct the supplied witness nor prove the source +theorem. + +## References + +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1034` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288` +- Blueprint `lem:qld-4-7`. +- Issue #351. +-/ + +open scoped BigOperators + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +namespace ExtendedLineGame + +variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real} +variable {setting : ProjectiveSetting P epsilon} +variable {points : CombinedPointsWitness setting deltaQ} + +/-- A pair of axis outcomes has zero Born mass if either coefficient vector +exceeds degree `d`. This is the degree-support conclusion of `lem:qld-4-13` +applied before any truncation or evaluation of the outcomes. -/ +theorem axis_coefficient_born_mass_eq_zero_of_unsupported +    (lines : ExtendedLinesWitness setting points deltaL) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (coefficientsA coefficientsB : DirectDegPoly P.extendedDirectLd (P.m * P.d + 1)) +    (hunsupported : (¬ ∀ index, P.d < index.val → coefficientsA index = 0) ∨ +      (¬ ∀ index, P.d < index.val → coefficientsB index = 0)) : +    DistanceCalculus.stateQForm (pairState setting) +      (heteroKron ((lines.Qline .alice line).effect coefficientsA) +        ((lines.Qline .bob line).effect coefficientsB)) = 0 := by +  rcases hunsupported with hA | hB +  · rw [lines.axis_degree .alice line coefficientsA hline hA] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] +  · rw [lines.axis_degree .bob line coefficientsB hline hB] +    simp [DistanceCalculus.stateQForm, heteroKron, applyOperatorToState] + +/-- Truncating an axis coefficient answer and evaluating it has exactly the +same measurement effects as evaluating the original answer. The discarded +coefficients vanish on every nonzero effect by the final assertion of +`lem:qld-4-13`, encoded in `ExtendedLinesWitness.axis_degree`. -/ +theorem axis_parameter_evaluation_effect_eq +    (lines : ExtendedLinesWitness setting points deltaL) (side : PlayerSide) +    (line : DirectLineDesc P.extendedDirectLd) (hline : line.kind = .axis) +    (parameter value : DirectScalarQ P.extendedDirectLd) : +    ((((lines.Qline side line).postprocess (axisRead P)).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) = +      (((lines.Qline side line).postprocess +        (fun coefficients => evalCoefficient coefficients parameter)).effect value) := by +  classical +  rw [MIPStarRE.Quantum.Measurement.postprocess_comp] +  simp only [MIPStarRE.Quantum.Measurement.postprocess_effect, Finset.sum_filter] +  apply Finset.sum_congr rfl +  intro coefficients _ +  by_cases heffect : (lines.Qline side line).effect coefficients = 0 +  · simp [heffect] +  · rw [axisRead_eval_of_effect_ne_zero lines side line hline coefficients heffect] + +/-- The axis coefficient-evaluation defect is exactly the parameter-evaluation +defect of the supplied strategy. The identity uses finite postprocessing and +the unchanged product of the axis-line marginal with a uniform parameter; +it introduces no degree, projectivity, or passing-value hypothesis. -/ +theorem axis_parameter_evaluated_coefficient_defect_eq +    (lines : ExtendedLinesWitness setting points deltaL) : +    axisParameterEvaluatedCoefficientDefect lines = +      axisParameterEvaluationDefect lines := by +  classical +  let readAxis : DirectLdAnswer P.extendedDirectLd → +      DirectDegPoly P.extendedDirectLd P.d := fun answer => +    match answer with +    | .alinePolys coefficients => coefficients ⟨0, by change 0 < 1; decide⟩ +    | _ => 0 +  let law := Distribution.prod (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (uniformDistribution (DirectScalarQ P.extendedDirectLd)) +  have heffect (side : PlayerSide) (sample : DirectLdSpace P.extendedDirectLd) +      (parameter value : DirectScalarQ P.extendedDirectLd) : +      ((((lines.Qline side (directALineDescOf P.extendedDirectLd sample)).postprocess +          (axisRead P)).postprocess +            (fun coefficients => evalCoefficient coefficients parameter)).effect value) = +        (((answerMeasurement lines side +          (.aline, directLdMap P.extendedDirectLd .aline sample)).postprocess +            (fun answer => evalCoefficient (readAxis answer) parameter)).effect value) := by +    unfold answerMeasurement +    rw [axis_description_canonical] +    rw [MIPStarRE.Quantum.Measurement.postprocess_comp, +      MIPStarRE.Quantum.Measurement.postprocess_comp] +    rfl +  have hmeasurement : axisParameterEvaluatedCoefficientDefect lines = +      consistencyDefect law +        (fun sample value => heteroKron +          (((answerMeasurement lines .alice +            (.aline, directLdMap P.extendedDirectLd .aline sample.1)).postprocess +              (fun answer => evalCoefficient (readAxis answer) sample.2)).effect value) 1) +        (fun sample value => heteroKron 1 +          (((answerMeasurement lines .bob +            (.aline, directLdMap P.extendedDirectLd .aline sample.1)).postprocess +              (fun answer => evalCoefficient (readAxis answer) sample.2)).effect value)) +        (pairState setting) := by +    unfold axisParameterEvaluatedCoefficientDefect consistencyDefect +    dsimp only [law] +    simp only [SandwichProduct.avgOver_distribution_prod, directALinePointDist, +      Distribution.avgOver_map] +    apply avgOver_congr +    intro sample +    apply avgOver_congr +    intro parameter +    apply Finset.sum_congr rfl +    intro valueA _ +    apply Finset.sum_congr rfl +    intro valueB _ +    rw [heffect .alice sample parameter valueA, heffect .bob sample parameter valueB] +  rw [hmeasurement] +  change consistencyDefect law +      (fun sample value => heteroKron +        ((((strategy lines).A +          (.aline, directLdMap P.extendedDirectLd .aline sample.1)).postprocess +            (fun answer => evalCoefficient (readAxis answer) sample.2)).effect value) 1) +      (fun sample value => heteroKron 1 +        ((((strategy lines).B +          (.aline, directLdMap P.extendedDirectLd .aline sample.1)).postprocess +            (fun answer => evalCoefficient (readAxis answer) sample.2)).effect value)) +      (strategy lines).ψ = _ +  rw [WinImplications.consistencyDefect_postprocess_eq_mismatch] +  unfold axisParameterEvaluationDefect +  simp only [law, SandwichProduct.avgOver_distribution_prod, directALinePointDist, +    Distribution.avgOver_map] +  rfl + +end ExtendedLineGame + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean b/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean new file mode 100644 index 00000000..12a9f33a --- /dev/null +++ b/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean @@ -0,0 +1,159 @@ +import MIPStarRE.QPBT.Combining.ExtendedLineGame.ParameterEvaluatedLineBound +import MIPStarRE.QPBT.Combining.ExtendedLineGame.SameLineCoefficientBound +import MIPStarRE.QPBT.Observables.WinImplications.Averages + +/-! +# Transport for the diagonal parameter defect + +This module identifies the diagonal coefficient defect used in the same-line +rejection bound with the diagonal parameter-evaluation defect used in the +supplied-line comparison. The proof composes the measurement postprocessings +and uses `diagonalRead_eval` to compare the two coefficient readers. + +The equality is a formalization-only bridge supporting the classical-game +construction in the proof of `lem:qld-4-7`. It retains the original diagonal +line marginal, including zero directions, and introduces no new hypotheses. + +## References + +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1034` +- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288` +- Blueprint `lem:qld-4-7`. +- Issue #353. +-/ + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum + +noncomputable section + +namespace ExtendedLineGame + +variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real} +variable {setting : ProjectiveSetting P epsilon} +variable {points : CombinedPointsWitness setting deltaQ} + +/-- The independently evaluated diagonal coefficient defect equals the +diagonal parameter-evaluation defect of the direct-game strategy. -/ +theorem diagonal_parameter_evaluated_coefficient_defect_eq +    (lines : ExtendedLinesWitness setting points deltaL) : +    diagonalParameterEvaluatedCoefficientDefect lines = +      diagonalParameterEvaluationDefect lines := by +  classical +  let readDiagonal : DirectLdAnswer P.extendedDirectLd → +      DirectDegPoly P.extendedDirectLd +        (P.extendedDirectLd.m * P.extendedDirectLd.d) := fun answer => +    match answer with +    | .dlinePolys coefficients => coefficients ⟨0, by change 0 < 1; decide⟩ +    | _ => 0 +  let μ := Distribution.prod (uniformDistribution (DirectLdSpace P.extendedDirectLd)) +    (uniformDistribution (DirectScalarQ P.extendedDirectLd)) +  have hmeasurement : +      diagonalParameterEvaluatedCoefficientDefect lines = +        consistencyDefect μ +          (fun sample value => heteroKron +            (((answerMeasurement lines .alice +              (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess +                (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value) 1) +          (fun sample value => heteroKron 1 +            (((answerMeasurement lines .bob +              (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess +                (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value)) +          (pairState setting) := by +    unfold diagonalParameterEvaluatedCoefficientDefect consistencyDefect +    dsimp only [μ] +    simp only [SandwichProduct.avgOver_distribution_prod, directDLinePointDist, +      Distribution.map_map, Distribution.avgOver_map] +    apply avgOver_congr +    intro sample +    apply avgOver_congr +    intro parameter +    have hA (value : DirectScalarQ P.extendedDirectLd) : +        heteroKron +            (((lines.Qline .alice +              (directDLineDescOf P.ext